fn a_render_callbacks_destructuring_default_is_the_props_default() {
    let output = extract_file(&format!(
        "{LOCAL_FACTORY}
export const Sized = make('div', ({{ size = 'M' }}: {{ size?: 'S' | 'M' }}) => <div />);
